import './list-workspace.css';

type Item = { id: string; title: string; description?: string };
type Props = { items?: Item[]; loading: boolean; refreshing?: boolean; error?: string; onRetry: () => void };

export function ListWorkspace({ items, loading, refreshing = false, error, onRetry }: Props) {
  const initial = loading && items === undefined;
  return <section className="listWorkspace" aria-labelledby="workspace-title" aria-busy={loading}>
    <header><div><h1 id="workspace-title">Items</h1><p>{items ? `${items.length} item${items.length === 1 ? '' : 's'}` : 'Workspace items'}</p></div>{refreshing && <span className="refreshStatus" role="status"><span className="spinner" aria-hidden="true" /> Refreshing…</span>}</header>
    {error && <div className="inlineError" role="alert"><span aria-hidden="true">!</span><div><strong>{items ? 'Could not refresh items' : 'Could not load items'}</strong><p>{error}</p><button type="button" onClick={onRetry}>Try again</button></div></div>}
    {initial ? <div className="skeletons" role="status"><span className="srOnly">Loading items…</span>{[1,2,3].map(row => <div className="skeleton" aria-hidden="true" key={row} />)}</div> : items?.length === 0 ? <div className="emptyState"><span aria-hidden="true">◇</span><h2>No items yet</h2><p>Items added to this workspace will appear here.</p></div> : items && <ul className={refreshing ? 'isRefreshing' : undefined}>{items.map(item => <li key={item.id}><h2>{item.title}</h2>{item.description && <p>{item.description}</p>}</li>)}</ul>}
  </section>;
}

