.listWorkspace { max-inline-size: 52rem; margin-inline: auto; color: #202026; }
.listWorkspace > header { min-block-size: 3.5rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; border-block-end: 1px solid #dedee4; }
.listWorkspace h1, .listWorkspace h2, .listWorkspace p { margin: 0; }
.listWorkspace h1 { font-size: 1.25rem; } .listWorkspace header p { margin-block-start: .2rem; color: #6b6b75; font-size: .8125rem; }
.refreshStatus { display: inline-flex; align-items: center; gap: .4rem; color: #555560; font-size: .8125rem; }
.spinner { inline-size: .875rem; block-size: .875rem; border: 2px solid #c8c8d0; border-block-start-color: #4f46e5; border-radius: 50%; animation: spin .8s linear infinite; }
.inlineError { display: flex; gap: .75rem; margin-block: 1rem; padding: .875rem; border: 1px solid #c43a3a; border-radius: .5rem; background: #fff4f4; } .inlineError > span { display: grid; place-items: center; inline-size: 1.5rem; block-size: 1.5rem; border-radius: 50%; background: #a82121; color: white; font-weight: 700; } .inlineError p { margin-block: .25rem .625rem; }
.inlineError button { min-block-size: 2rem; }
.listWorkspace ul { margin: 0; padding: 0; list-style: none; } .listWorkspace li { padding-block: .875rem; border-block-end: 1px solid #e5e5e9; } .listWorkspace li h2 { font-size: .9375rem; } .listWorkspace li p { margin-block-start: .25rem; color: #62626c; }
.isRefreshing { opacity: .72; }
.emptyState { padding: 4rem 1rem; text-align: center; } .emptyState > span { font-size: 2rem; } .emptyState h2 { margin-block-start: .75rem; } .emptyState p { margin-block-start: .35rem; color: #666670; }
.skeleton { block-size: 3.75rem; margin-block: .75rem; border-radius: .375rem; background: linear-gradient(90deg,#ececf0 25%,#f7f7f9 50%,#ececf0 75%); background-size: 200% 100%; animation: shimmer 1.4s infinite; }
.srOnly { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip: rect(0 0 0 0); }
@keyframes spin { to { transform: rotate(360deg); } } @keyframes shimmer { to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) { .spinner, .skeleton { animation: none; } }
